window.AUTH=window.AUTH||{};window.AUTH["21-511"]={"d":"21-511","id":"2021/21-511","n":"Shoop v. Twyford","briefs":[{"k":"petitioner","label":"Brief of petitioner Tim Shoop","date":"2022-02-25","url":"https://www.supremecourt.gov/DocketPDF/21/21-511/214952/20220225080120015_Twyford%20Petitioner%20Brief.PDF","side":"pet","n":61},{"k":"united-states","label":"Brief amicus curiae of United States in support of neither party","date":"2022-03-07","url":"https://www.supremecourt.gov/DocketPDF/21/21-511/217910/20220307185350603_No.%2021-511%20Shoop.pdf","side":"us","n":54},{"k":"respondent","label":"Brief of respondent Raymond Twyford","date":"2022-03-28","url":"https://www.supremecourt.gov/DocketPDF/21/21-511/219593/20220328134645925_21-511%20Brief%20for%20the%20Respondent.pdf","side":"res","n":45},{"k":"reply","label":"Reply of petitioner Tim Shoop","date":"2022-04-05","url":"https://www.supremecourt.gov/DocketPDF/21/21-511/220344/20220405165158873_Twyford%20Reply%20Brief.PDF","side":"pet","n":69}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/596us2r50_2034.pdf","tr":true,"items":[{"t":"case","label":"Allied Chem. Corp. v. Daiflon, Inc.","cite":"449 U.S. 33","y":1980,"id":"1980/79-1895","sc":1,"sum":"Where the District Court, because of error in certain of its evidentiary rulings in respondent's private antitrust action, had entered a nonappealable interlocutory order granting a new trial after the jury had returned a verdict for respondent, the Court of Appeals erred in issuing a writ of mandamus directing the trial court to restore the verdict as to liability but permitting a new trial on damages. The remedy …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 40","3":"20"}},{"t":"case","label":"Ballard v. Spradley","cite":"557 F.2d 476","y":1977,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/557/476/","op":2,"by":{"0":"3"}},{"t":"case","label":"Bank of United States v. Halstead","cite":"23 U.S. 51","y":1825,"id":"scdb/1825-007","sc":1,"op":1,"sum":"The Bank of the United States v. Halstead.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"21","3":"15"}},{"t":"case","label":"Barnes v. Black","cite":"544 F.3d 807","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/544/807/","op":2,"ar":1,"by":{"0":"3","2":"26, 37"}},{"t":"case","label":"Blevins v. Warden","cite":"2011 WL 6141062","y":2011,"court":"S.D. Ohio Dec. 9","by":{"0":"43"}},{"t":"case","label":"Bracy v. Gramley","cite":"520 U.S. 899","y":1997,"id":"1996/96-6133","sc":1,"op":1,"sum":"The Court held that Bracy had made a sufficient factual showing to establish \"good cause,\" as required by Habeas Corpus Rule 6(a), for discovery on his claim of actual judicial bias in his case.","sumSrc":"Oyez","by":{"0":"12, 16, 43","1":"2, 7, 28","2":"46","3":"22"}},{"t":"case","label":"Carbo v. United States","cite":"364 U.S. 611","y":1961,"id":"1960/72","sc":1,"ar":1,"sum":"Under 28 U. S. C. § 2241, the United States District Court for the Southern District of California had jurisdiction in the circumstances of this case to issue a writ of habeas corpus ad prosequendum directing a New York City prison official to deliver petitioner, a prisoner of that City, to California for trial on an indictment pending there in the District Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30","1":"19","2":"37"}},{"t":"case","label":"Carlisle v. United States","cite":"517 U.S. 416","y":1996,"id":"1995/94-9247","sc":1,"sum":"The Court held that the District Court had no authority to grant the petitioner's motion for judgment of acquittal filed one day outside the Rule 29(c) time limit.","sumSrc":"Oyez","by":{"0":"passim","1":"11","3":"2, 17"}},{"t":"case","label":"Cheney v. United States Dist. Court","cite":"542 U.S. 367","y":2004,"id":"2003/03-475","sc":1,"sum":"The Court sent the case back to the D.C. Court of Appeals, arguing that the appellate court should have considered separation-of-powers claims and was wrong to conclude it lacked authority to order District Court discovery to stop.","sumSrc":"Oyez","by":{"0":"40","3":"7"}},{"t":"case","label":"Clinton v. Goldsmith","cite":"526 U.S. 529","y":1999,"id":"1998/98-347","sc":1,"sum":"The Court held that because the Court of Appeals for the Armed Forces' resort to the All Writs Act was neither in aid of its strictly circumscribed jurisdiction to review court-martial findings and sentences nor \"necessary or appropriate\" in light of a servicemember's alternative opportunities to seek relief, that court lacked jurisdiction to issue an injunction against dropping Goldsmith from the Air Force rolls.","sumSrc":"Oyez","by":{"0":"23, 34, 39, 46","1":"10, 11, 17","3":"2"}},{"t":"case","label":"Cornwell v. Bradshaw","cite":"559 F.3d 398","y":2009,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/559/398/","by":{"0":"48"}},{"t":"case","label":"Cullen v. Pinholster","cite":"563 U.S. 170","y":2011,"id":"2010/09-1088","sc":1,"op":3,"ar":1,"sum":"The Court held that a federal court could not overturn a state criminal conviction on the basis of the facts the defendant could have alleged, but did not, in state court.","sumSrc":"Oyez","by":{"0":"passim","1":"5, 26, 27","2":"4, 43","3":"21"}},{"t":"case","label":"DA’s Office v. Osborne","cite":"557 U.S. 52","y":2009,"id":"2008/08-6","sc":1,"sum":"The Court found that the defendant had no constitutional right to obtain post-conviction access to DNA evidence used against him at trial.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Davila v. Davis","cite":"137 S. Ct. 2058","y":2017,"id":"2016/16-6219","sc":1,"op":1,"sum":"The Court determined that ineffective assistance of appellate counsel does not overcome the procedural default of ineffective assistance of counsel claims.","sumSrc":"Oyez","by":{"0":"45, 46"}},{"t":"case","label":"De Beers Consol. Mines, Ltd. v. United States","cite":"325 U.S. 212","y":1945,"id":"scdb/1944-154","sc":1,"sum":"Statement of the Case.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13, 24"}},{"t":"case","label":"Dep’t of Homeland Sec. v. Thuraissigiam","cite":"140 S. Ct. 1959","y":2020,"id":"2019/19-161","sc":1,"sum":"The Court held that 8 U.S.C. § 1252(e)(2) as applied to the respondent Thuraissigiam does not violate the Suspension Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"28","1":"18"}},{"t":"case","label":"Dig. Equip. Corp. v. Desktop Direct, Inc.","cite":"511 U.S. 863","y":1994,"id":"1993/93-405","sc":1,"op":4,"sum":"The Supreme Court ruled that the denial of immunity - while cause for concern - does not automatically create a right to immediate appeal. It is important to have final judgments before appeals are made, Justice David H. Souter wrote for the Court, and exceptions should only be made in particularly important cases.","sumSrc":"Oyez","by":{"0":"2, 3","2":"19, 21, 22, 24"}},{"t":"case","label":"Edwards v. Vannoy","cite":"141 S. Ct. 1547","y":2021,"id":"2020/19-5807","sc":1,"sum":"The jury-unanimity rule announced in Ramos v. Louisiana, 590 U. S. ___, does not apply retroactively on federal collateral review.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"passim","3":"9"}},{"t":"case","label":"Hardwick v. Doolittle","cite":"558 F.2d 292","y":1977,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/558/292/","by":{"0":"25"}},{"t":"case","label":"Harrington v. Richter","cite":"562 U.S. 86","y":2011,"id":"2010/09-587","sc":1,"op":2,"sum":"The Court held that a defense lawyer was not deficient for failing to consult blood evidence when planning strategy for trial.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Harris v. Nelson","cite":"394 U.S. 286","y":1969,"id":"1968/199","sc":1,"op":1,"sum":"Recognizing, before AEDPA, that a writ is “necessary or appropriate in aid of ” a federal habeas court's jurisdiction if “specifc allegations” show that the petitioner may, “if the facts are fully developed,” be able to demonstrate that he is “entitled to relief ”.","sumSrc":"opinion","by":{"0":"17, 42, 43, 48","1":"12, 15, 27, 28","2":"passim","3":"15, 18, 22"}},{"t":"case","label":"Hohn v. United States","cite":"524 U.S. 236","y":1998,"id":"1997/96-8986","sc":1,"sum":"This decision overrules that portion of House v. Mayo, 324 U.S. 42, 44 (1945) (per curiam), which held that the Court lacks statutory certiorari jurisdiction to review denials of certificates of probable cause.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Home Depot U.S.A., Inc. v. Jackson","cite":"139 S. Ct. 1743","y":2019,"id":"2018/17-1471","sc":1,"sum":"Neither the general removal provision, 28 U. S. C. §1441(a), nor the removal provision in the Class Action Fairness Act of 2005, §1453(b), permit a third-party counterclaim defendant to remove a class-action claim from state to federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25"}},{"t":"case","label":"I.N.S. v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Ivey v. Harney","cite":"47 F.3d 181","y":1995,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/47/181/","ar":1,"by":{"0":"passim","1":"14","2":"33","3":"passim"}},{"t":"case","label":"Jackson v. Vasquez","cite":"1 F.3d 885","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/1/885/","op":2,"by":{"0":"3, 34","2":"26"}},{"t":"case","label":"Jones v. Lilly","cite":"37 F.3d 964","y":1994,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/37/964/","op":2,"by":{"0":"passim","3":"3, 7, 15"}},{"t":"case","label":"Jurado v. Davis","cite":"12 F.4th 1084","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/12/1084/","by":{"0":"43"}},{"t":"case","label":"Lafferty v. Benzon","cite":"933 F.3d 1237","y":2019,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/933/1237/","by":{"0":"43"}},{"t":"case","label":"Leavitt v. Arave","cite":"682 F.3d 1138","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/682/1138/","by":{"0":"48"}},{"t":"case","label":"Lowery v. McCaughtry","cite":"954 F.2d 422","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/954/422/","by":{"0":"25","3":"8, 14, 15"}},{"t":"case","label":"NFIB v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"sum":"Cases in which the Court held that the minimum coverage requirement of the Affordable Care Act was constitutional, that Congress had the power to enforce the taxation of most Americans that did not buy the minimum level of coverage, and that the federal government exceeded its power by pressuring States into accepting conditions that Congress could not impose directly by threatening to withhold all federal funding under Medicaid.","sumSrc":"Oyez","by":{"0":"22, 34"}},{"t":"case","label":"Pa. Bureau of Corr. v. U.S. Marshals Serv.","cite":"474 U.S. 34","y":1985,"id":"1985/84-489","sc":1,"op":4,"ar":2,"sum":"There is no statutory authority for the order in question.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"10, 11, 14, 19, 22","2":"passim","3":"passim"}},{"t":"case","label":"Price v. Johnston","cite":"334 U.S. 266","y":1948,"id":"scdb/1947-084","sc":1,"op":1,"sum":"1. Under § 262 of the Judicial Code, a circuit court of appeals has power, exercisable in the sound discretion of the court, to issue an order, in the nature of a writ of habeas corpus, commanding that a prisoner be brought before the court for the purpose of arguing his own appeal in a case involving his life or liberty.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24","1":"12, 16, 17, 20, 23","2":"passim","3":"passim"}},{"t":"case","label":"Pulliam v. Allen","cite":"466 U.S. 522","y":1984,"id":"1983/82-1432","sc":1,"sum":"The Court held that the precedent set by British common law relied on the issuance of writs, rather than the imposition of judicial immunity, to protect judicial independence. The United States never had a doctrine of judicial immunity from prospective relief, and there was no evidence that the lack of that protection created a chilling effect on judicial independence.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Rawlins v. Kansas","cite":"714 F.3d 1189","y":2013,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/714/1189/","by":{"0":"25"}},{"t":"case","label":"Roche v. Evaporated Milk Ass’n","cite":"319 U.S. 21","y":1943,"id":"scdb/1942-071","sc":1,"sum":"1. The Circuit Court of Appeals is empowered by § 262 of theJudicial..Code to issue all writs, not specifically provided for by statute, which may be necessary for the exercise of its jurisdiction, agreeably to the usages and principles of law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 40"}},{"t":"case","label":"Ryan v. Gonzales","cite":"568 U.S. 57","y":2013,"id":"2012/10-930","sc":1,"sum":"The Court held that no right to competence exists during federal habeas corpus proceedings.","sumSrc":"Oyez","by":{"0":"49","1":"13"}},{"t":"case","label":"Sibbald v. United States","cite":"37 U.S. 488","y":1838,"id":"scdb/1838-037","sc":1,"op":1,"sum":"On an appeal from-the superior court of East Florida by the United States, the decree of-the court of East Florida was in part affirmed; the.title of Sibbald., the appellee,.to whonvthe grant of land had been made by the -Spanish governor, before the cdssion of'Florida, having been deemed Valid by the Supreme Court. The decree of the Supreme Court directed the surveyor of ptiblie lands in East Flo-1 rida to do a.ll …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Syngenta Crop Prot., Inc. v. Henson","cite":"537 U.S. 28","y":2002,"id":"2002/01-757","sc":1,"op":1,"ar":2,"sum":"The Court held that the All Writs Act does not provide removal jurisdiction.","sumSrc":"Oyez","by":{"0":"23","1":"11","3":"16"}},{"t":"case","label":"Thomas v. Taylor","cite":"170 F.3d 466","y":1999,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/170/466/","by":{"0":"48"}},{"t":"case","label":"Twyford v. Shoop","cite":"11 F.4th 518","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/11/518/","op":5,"by":{"0":"2"}},{"t":"case","label":"Twyford v. Warden","cite":"2020 WL 1308318","y":2020,"court":"S.D. Ohio Mar. 19","op":1,"by":{"0":"2"}},{"t":"case","label":"U.S. Alkali Export Ass’n v. United States","cite":"325 U.S. 196","y":1945,"id":"scdb/1944-087","sc":1,"sum":"1. An order of a district court in a suit brought by the United States under § 4 of the Sherman Act against export associations and members thereof to restrain violations of the Act, denying a motion of.the defendants to dismiss, made on the ground that, under §§ 1, 2 and 5 of the Webb-Pomerene Act, exclusive jurisdiction of the matters charged in the complaint is vested in the first instance in the Federal Trade …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21","1":"11"}},{"t":"case","label":"United States v. Blake","cite":"868 F.3d 960","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/868/960/","by":{"0":"21"}},{"t":"case","label":"United States v. Denedo","cite":"556 U.S. 904","y":2009,"id":"2008/08-267","sc":1,"sum":"The Court held that the Navy-Marine Corps Court of Criminal Appeals (NMCCA) retained jurisdiction under the All Writs Act to consider coram nobis petitions that alleged a prior judgment of conviction was fundamentally flawed.","sumSrc":"Oyez","by":{"0":"22, 23","1":"10"}},{"t":"case","label":"United States v. Hayman","cite":"342 U.S. 205","y":1952,"id":"scdb/1951-024","sc":1,"ar":1,"sum":"The District Court erred in determining the factual issues raised by respondent's motion under § 2255 without notice to respondent and without his presence.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"12, 16, 23","2":"30, 31, 35, 39","3":"13, 14"}},{"t":"case","label":"United States v. Morgan","cite":"346 U.S. 502","y":1954,"id":"scdb/1953-020","sc":1,"sum":"Under the All-Writs Section, 28 U. S. C. § 1651 (a), the Federal District Court had power to issue a writ of error coram nobis;.it had power to vacate its judgment of conviction and sentence; and respondent is entitled to an opportunity to show that his federal conviction was invalid.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 22"}},{"t":"case","label":"United States v. New York Tel. Co.","cite":"434 U.S. 159","y":1977,"id":"1977/76-835","sc":1,"ar":1,"sum":"On the basis of an FBI affidavit stating that certain individuals were conducting an illegal gambling enterprise at a specified New York City address and that there was probable cause to believe that two telephones with different numbers were being used there to further the illegal activity, the District Court authorized the FBI to install and use pen registers with respect to the two telephones, and directed …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 23, 27, 34","1":"11, 12, 16","2":"passim","3":"15, 16, 19"}},{"t":"case","label":"Vega v. Semple","cite":"963 F.3d 259","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/963/259/","by":{"0":"38"}},{"t":"case","label":"Wainwright v. Sykes","cite":"433 U.S. 72","y":1977,"id":"1976/75-1578","sc":1,"op":1,"sum":"Respondent's failure to make timely objection under the Florida contemporaneous-objection rule to the admission of his inculpatory statements, absent a showing of cause for the noncompliance and some showing of actual prejudice, bars federal habeas corpus review of his Miranda claim. Davis v. United States, 411 U. S. 233; Francis v. Henderson,425 U. S. 536.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"50"}},{"t":"case","label":"Washington v. United States","cite":"460 U.S. 536","y":1983,"id":"1982/81-969","sc":1,"sum":"The Washington statutes are not invalid under the Supremacy Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"usc","label":"18 U.S.C. § 3599","url":"https://www.law.cornell.edu/uscode/text/18/3599","stext":{"head":"§3599. Counsel for financially unable defendants","paras":[[0,"(a)(1) Notwithstanding any other provision of law to the contrary, in every criminal action in which a defendant is charged with a crime which may be punishable by death, a defendant who is or becomes financially unable to obtain adequate representation or investigative, expert, or other reasonably necessary services at any time either—"],[1,"(A) before judgment; or"],[1,"(B) after the entry of a judgment imposing a sentence of death but before the execution of that judgment;"],[0,"shall be entitled to the appointment of one or more attorneys and the furnishing of such other services in accordance with subsections (b) through (f)."],[0,"(2) In any post conviction proceeding under section 2254 or 2255 of title 28, United States Code, seeking to vacate or set aside a death sentence, any defendant who is or becomes financially unable to obtain adequate representation or investigative, expert, or other reasonably necessary services shall be entitled to the appointment of one or more attorneys and the furnishing of such other services in accordance with subsections (b) through (f)."],[0,"(b) If the appointment is made before judgment, at least one attorney so appointed must have been admitted to practice in the court in which the prosecution is to be tried for not less than five years, and must have had not less than three years experience in the actual trial of felony prosecutions in that court."],[0,"(c) If the appointment is made after judgment, at least one attorney so appointed must have been admitted to practice in the court of appeals for not less than five years, and must have had not less than three years experience in the handling of appeals in that court in felony cases."],[0,"(d) With respect to subsections (b) and (c), the court, for good cause, may appoint another attorney whose background, knowledge, or experience would otherwise enable him or her to properly represent the defendant, with due consideration to the seriousness of the possible penalty and to the unique and complex nature of the litigation."],[0,"(e) Unless replaced by similarly qualified counsel upon the attorney's own motion or upon motion of the defendant, each attorney so appointed shall represent the defendant throughout every subsequent stage of available judicial proceedings, including pretrial proceedings, trial, sentencing, motions for new trial, appeals, applications for writ of certiorari to the Supreme Court of the United States, and all available post-conviction process, together with applications for stays of execution and other appropriate motions and procedures, and shall also represent the defendant in such competency proceedings and proceedings for executive or other clemency as may be available to the defendant."],[0,"(f) Upon a finding that investigative, expert, or other services are reasonably necessary for the representation of the defendant, whether in connection with issues relating to guilt or the sentence, the court may authorize the defendant's attorneys to obtain such services on behalf of the defendant and, if so authorized, shall order the payment of fees and expenses therefor under subsection (g). No ex parte proceeding, communication, or request may be considered pursuant to this section unless a proper showing is made concerning the need for confidentiality. Any such proceeding, communication, or request shall be transcribed and made a part of the record available for appellate review."],[0,"(g)(1) Compensation shall be paid to attorneys appointed under this subsection 1 at a rate of not more than $125 per hour for in-court and out-of-court time. The Judicial Conference is authorized to raise the maximum for hourly payment specified in the 2 paragraph up to the aggregate of the overall average percentages of the adjustments in the rates of pay for the General Schedule made pursuant to section 5305 3 of title 5 on or after such date. After the rates are raised under the preceding sentence, such hourly range may be raised at intervals of not less than one year, up to the aggregate of the overall average percentages of such adjustments made since the last raise under this paragraph."],[0,"(2) Fees and expenses paid for investigative, expert, and other reasonably necessary services authorized under subsection (f) shall not exceed $7,500 in any case, unless payment in excess of that limit is certified by the court, or by the United States magistrate judge, if the services were rendered in connection with the case disposed of entirely before such magistrate judge, as necessary to provide fair compensation for services of an unusual character or duration, and the amount of the excess payment is approved by the chief judge of the circuit. The chief judge of the circuit may delegate such approval authority to an active or senior circuit judge."],[0,"(3) The amounts paid under this paragraph 4 for services in any case shall be disclosed to the public, after the disposition of the petition."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3599?type=usc&year=mostrecent&link-type=html"},"head":"§3599. Counsel for financially unable defendants","tname":"Crimes and Criminal Procedure","by":{"0":"11, 37, 38","2":"10, 11, 44","3":"21"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"3"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","stext":{"head":"§1291. Final decisions of district courts","paras":[[0,"The courts of appeals (other than the United States Court of Appeals for the Federal Circuit) shall have jurisdiction of appeals from all final decisions of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, except where a direct review may be had in the Supreme Court. The jurisdiction of the United States Court of Appeals for the Federal Circuit shall be limited to the jurisdiction described in sections 1292(c) and (d) and 1295 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1291?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1291. Final decisions of district courts","tname":"Judiciary and Judicial Procedure","by":{"0":"2","2":"1, 18, 19","3":"1, 5, 6"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","by":{"0":"2"}},{"t":"usc","label":"28 U.S.C. § 1651","url":"https://www.law.cornell.edu/uscode/text/28/1651","subs":["(a)"],"stext":{"head":"§1651. Writs","paras":[[0,"(a) The Supreme Court and all courts established by Act of Congress may issue all writs necessary or appropriate in aid of their respective jurisdictions and agreeable to the usages and principles of law."],[0,"(b) An alternative writ or rule nisi may be issued by a justice or judge of a court which has jurisdiction."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1651?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1651. Writs","tname":"Judiciary and Judicial Procedure","by":{"0":"passim","1":"passim","2":"2, 27, 28","3":"7, 20"}},{"t":"usc","label":"28 U.S.C. § 2241","url":"https://www.law.cornell.edu/uscode/text/28/2241","subs":["(c)(1964)","(c)","(c)(5)","(c)(3)"],"stext":{"head":"§2241. Power to grant writ","paras":[[0,"(a) Writs of habeas corpus may be granted by the Supreme Court, any justice thereof, the district courts and any circuit judge within their respective jurisdictions. The order of a circuit judge shall be entered in the records of the district court of the district wherein the restraint complained of is had."],[0,"(b) The Supreme Court, any justice thereof, and any circuit judge may decline to entertain an application for a writ of habeas corpus and may transfer the application for hearing and determination to the district court having jurisdiction to entertain it."],[0,"(c) The writ of habeas corpus shall not extend to a prisoner unless—"],[1,"(1) He is in custody under or by color of the authority of the United States or is committed for trial before some court thereof; or"],[1,"(2) He is in custody for an act done or omitted in pursuance of an Act of Congress, or an order, process, judgment or decree of a court or judge of the United States; or"],[1,"(3) He is in custody in violation of the Constitution or laws or treaties of the United States; or"],[1,"(4) He, being a citizen of a foreign state and domiciled therein is in custody for an act done or omitted under any alleged right, title, authority, privilege, protection, or exemption claimed under the commission, order or sanction of any foreign state, or under color thereof, the validity and effect of which depend upon the law of nations; or"],[1,"(5) It is necessary to bring him into court to testify or for trial."],[0,"(d) Where an application for a writ of habeas corpus is made by a person in custody under the judgment and sentence of a State court of a State which contains two or more Federal judicial districts, the application may be filed in the district court for the district wherein such person is in custody or in the district court for the district within which the State court was held which convicted and sentenced him and each of such district courts shall have concurrent jurisdiction to entertain the application. The district court for the district wherein such an application is filed in the exercise of its discretion and in furtherance of justice may transfer the application to the other district court for hearing and determination."],[0,"(e)(1) No court, justice, or judge shall have jurisdiction to hear or consider an application for a writ of habeas corpus filed by or on behalf of an alien detained by the United States who has been determined by the United States to have been properly detained as an enemy combatant or is awaiting such determination."],[0,"(2) Except as provided in paragraphs (2) and (3) of section 1005(e) of the Detainee Treatment Act of 2005 (10 U.S.C. 801 note), no court, justice, or judge shall have jurisdiction to hear or consider any other action against the United States or its agents relating to any aspect of the detention, transfer, treatment, trial, or conditions of confinement of an alien who is or was detained by the United States and has been determined by the United States to have been properly detained as an enemy combatant or is awaiting such determination."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2241?type=usc&year=mostrecent&link-type=html"},"head":"§2241. Power to grant writ","tname":"Judiciary and Judicial Procedure","by":{"0":"passim","1":"23, passim, 5, 7, 8, 21, 23","2":"36, 37, 15, 31, 36, 37, 3, 37, 38","3":"passim"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","subs":["(d)","(d)(1)","(d)(2)","(e)(2)"],"stext":{"head":"§2254. State custody; remedies in Federal courts","paras":[[0,"(a) The Supreme Court, a Justice thereof, a circuit judge, or a district court shall entertain an application for a writ of habeas corpus in behalf of a person in custody pursuant to the judgment of a State court only on the ground that he is in custody in violation of the Constitution or laws or treaties of the United States."],[0,"(b)(1) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted unless it appears that—"],[1,"(A) the applicant has exhausted the remedies available in the courts of the State; or"],[1,"(B)(i) there is an absence of available State corrective process; or"],[1,"(ii) circumstances exist that render such process ineffective to protect the rights of the applicant."],[0,"(2) An application for a writ of habeas corpus may be denied on the merits, notwithstanding the failure of the applicant to exhaust the remedies available in the courts of the State."],[0,"(3) A State shall not be deemed to have waived the exhaustion requirement or be estopped from reliance upon the requirement unless the State, through counsel, expressly waives the requirement."],[0,"(c) An applicant shall not be deemed to have exhausted the remedies available in the courts of the State, within the meaning of this section, if he has the right under the law of the State to raise, by any available procedure, the question presented."],[0,"(d) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted with respect to any claim that was adjudicated on the merits in State court proceedings unless the adjudication of the claim—"],[1,"(1) resulted in a decision that was contrary to, or involved an unreasonable application of, clearly established Federal law, as determined by the Supreme Court of the United States; or"],[1,"(2) resulted in a decision that was based on an unreasonable determination of the facts in light of the evidence presented in the State court proceeding."],[0,"(e)(1) In a proceeding instituted by an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court, a determination of a factual issue made by a State court shall be presumed to be correct. The applicant shall have the burden of rebutting the presumption of correctness by clear and convincing evidence."],[0,"(2) If the applicant has failed to develop the factual basis of a claim in State court proceedings, the court shall not hold an evidentiary hearing on the claim unless the applicant shows that—"],[1,"(A) the claim relies on—"],[2,"(i) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[2,"(ii) a factual predicate that could not have been previously discovered through the exercise of due diligence; and"],[1,"(B) the facts underlying the claim would be sufficient to establish by clear and convincing evidence that but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(f) If the applicant challenges the sufficiency of the evidence adduced in such State court proceeding to support the State court's determination of a factual issue made therein, the applicant, if able, shall produce that part of the record pertinent to a determination of the sufficiency of the evidence to support such determination. If the applicant, because of indigency or other reason is unable to produce such part of the record, then the State shall produce such part of the record and the Federal court shall direct the State to do so by order directed to an appropriate State official. If the State cannot provide such pertinent part of the record, then the court shall determine under the existing facts and circumstances what weight shall be given to the State court's factual determination."],[0,"(g) A copy of the official records of the State court, duly certified by the clerk of such court to be a true and correct copy of a finding, judicial opinion, or other reliable written indicia showing such a factual determination by the State court shall be admissible in the Federal court proceeding."],[0,"(h) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel for an applicant who is or becomes financially unable to afford counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(i) The ineffectiveness or incompetence of counsel during Federal or State collateral post-conviction proceedings shall not be a ground for relief in a proceeding arising under section 2254."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2254?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§2254. State custody; remedies in Federal courts","tname":"Judiciary and Judicial Procedure","by":{"0":"passim","1":"passim, 4, 26, 5, 26, 29, 26, 28","2":"31, 37, 43"}},{"t":"rule","label":"Fed. R. Civ. P. 26","url":"https://www.law.cornell.edu/rules/frcp/rule_26","by":{"0":"48","2":"47"}},{"t":"rule","label":"Fed. R. Civ. P. 35","url":"https://www.law.cornell.edu/rules/frcp/rule_35","by":{"0":"48","3":"16, 17, 19, 20"}},{"t":"case","label":"American Lithographic Co. v. Werckmeister","cite":"221 U.S. 603","y":1911,"id":"scdb/1910-165","sc":1,"sum":"The forfeiture for infringement of copyright prescribed by § 4965, Rev. Stat., is not only for every copy found in possession of the infringer, but in the alternative for every copy by him sold.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"15","3":"15"}},{"t":"case","label":"Banister v. Davis","cite":"140 S. Ct. 1698","y":2020,"id":"2019/18-6943","sc":1,"sum":"The Court held that a timely Rule 59(e) motion to “amend or alter” a habeas court’s judgment is not a second or successive habeas petition.","sumSrc":"Oyez","by":{"1":"2"}},{"t":"case","label":"Barber v. Page","cite":"390 U.S. 719","y":1968,"id":"1967/703","sc":1,"sum":"Petitioner and one Woods were jointly charged with armed robbery. During the preliminary hearing Woods waived his privilege against self-incrimination and testified, incriminating petitioner. Petitioner's counsel did not cross-examine Woods. When petitioner was tried in Oklahoma seven months later, Woods was in a federal prison in Texas. The State of Oklahoma made no effort to obtain Woods' presence at trial but …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Bell v. Cone","cite":"535 U.S. 685","y":2002,"id":"2001/01-400","sc":1,"sum":"The Court held that Tennessee Court of Criminal Appeals's decision neither was \"contrary to\" nor involved \"an unreasonable application of clearly established Federal law\" under the provisions of 28 USC section 2254(d)(1).","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Christy v. Robinson","cite":"216 F. Supp. 2d 398","y":2002,"court":"D.N.J.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/216/398/","sum":"Noting that the court had ordered the state prison’s medical care provider to “arrange for” the prisoner plaintiff “to be examined by two independent doctors”.","sumSrc":"brief:1","by":{"1":"14"}},{"t":"case","label":"Cottle v. Nevada Dep’t of Corrs.","cite":"2013 WL 5773845","y":2013,"court":"D. Nev. Oct. 24","by":{"1":"15"}},{"t":"case","label":"Delker v. Maass","cite":"843 F. Supp. 1390","y":1994,"court":"D. Or.","url":"https://www.courtlistener.com/c/F.%20Supp./843/1390/","sum":"Explaining that the plaintiff “was examined by * * * a court appointed independent medical expert” “while the action was pending”.","sumSrc":"brief:1","by":{"1":"14"}},{"t":"case","label":"FTC v. Dean Foods","cite":"384 U.S. 597","y":1966,"id":"1965/970","sc":1,"sum":"Respondents, two substantial competitors in the sale of packaged milk in the Chicago area, signed a merger agreement following meetings with representatives of the Federal Trade Commission (FTC) who indicated that the merger would raise serious questions under the antitrust laws. At the time of the merger one of the respondents was the third or fourth largest packaged milk distributor in the area, the other at least …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"12"}},{"t":"case","label":"Gonzalez v. Thaler","cite":"565 U.S. 134","y":2012,"id":"2011/10-895","sc":1,"sum":"The Court held that a prisoner who does not seek review in a state’s highest court faces final judgment for the purposes of Section 2244(d)(1)(A) upon “expiration of the time for seeking such review.”","sumSrc":"Oyez","by":{"1":"2"}},{"t":"case","label":"Mayle v. Felix","cite":"545 U.S. 644","y":2005,"id":"2004/04-563","sc":1,"sum":"The Court rejected the argument that the trial itself was the \"transaction\" or \"occurrence\" under federal habeas law. The Court said that such a definition would have allowed virtually any new claim introduced in an amended petition to relate back, gutting the one-year time limit on petitions.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Preiser v. Rodriguez","cite":"411 U.S. 475","y":1973,"id":"1972/71-1369","sc":1,"sum":"When a state prisoner challenges the fact or duration of his physical imprisonment and by way of relief seeks a determination that he is entitled to immediate release or a speedier release, his sole federal remedy is a writ of habeas corpus.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Rasul v. Bush","cite":"542 U.S. 466","y":2004,"id":"2003/03-334","sc":1,"sum":"The Court ruled that United States courts have jurisdiction to consider legal appeals filed on behalf of foreign citizens held by the United States military in Guantanamo Bay Naval Base, Cuba.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Reaves v. Dep’t of Corr.","cite":"392 F. Supp. 3d 195","y":2019,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/392/195/","ar":3,"by":{"1":"24"}},{"t":"case","label":"Rees v. Peyton","cite":"384 U.S. 312","y":1966,"id":"scdb/1965-114","sc":1,"ar":2,"sum":"In aid of this Court's certiorari jurisdiction, the District Court is instructed to judicially determine Rees' competence after notice to the parties, psychiatric and other medical examinations, and such hearings as it deems suitable, and report its findings to this Court. S. White Rhyne, Jr., and Charles A. Dukes, Jr., for petitioner. Reno S. Harp III, Assistant Attorney General of Virginia, for respondent. Monroe …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"7, 12, 13, 23","2":"passim","3":"10, 11"}},{"t":"case","label":"Schriro v. Landrigan","cite":"550 U.S. 465","y":2007,"id":"2006/05-1575","sc":1,"op":3,"ar":1,"sum":"The Court reversed the Ninth Circuit and ruled that the District Court was within its discretion when it upheld Landrigan's sentence without granting him a new evidentiary hearing. The Justices split 5-4 with Justice Clarence Thomas writing the opinion for the majority. The Court rejected the Ninth's Circuit's holding that the District Court took out of context statements Landrigan made during his trial.","sumSrc":"Oyez","by":{"1":"28, 29"}},{"t":"case","label":"United States v. Hampton Rds. Reg’l Jail Auth.","cite":"2020 WL 5550918","y":2020,"court":"E.D.V.A. Aug. 5","by":{"1":"24"}},{"t":"case","label":"United States v. Mauro","cite":"436 U.S. 340","y":1978,"id":"1977/76-1596","sc":1,"sum":"After respondents in No. 76-1596, who at the time were serving state sentences in New York, were indicted on federal charges in the United States District Court for the Eastern District of New York, that court issued writs of habeas corpus ad prosequendum directing the state prison wardens to produce respondents in court. Subsequently, following their arraignments, respondents were retained in federal custody in New …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19, 21"}},{"t":"case","label":"Wilkins v. Gaddy","cite":"559 U.S. 34","y":2010,"id":"2009/08-10914","sc":1,"sum":"The Court held that a \"significant injury\" is not a threshold requirement for stating an excessive force claim.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Wisconsin Right to Life, Inc. v. FEC","cite":"542 U.S. 1305","y":2004,"url":"https://supreme.justia.com/cases/federal/us/542/1305/","sc":1,"by":{"1":"12"}},{"t":"case","label":"Wood v. Milyard","cite":"566 U.S. 463","y":2012,"id":"2011/10-9995","sc":1,"sum":"The Court held that, under Day v. McDonough, appellate courts have the authority, though not the obligation, to raise a forfeited statute of limitations defense on its own.","sumSrc":"Oyez","by":{"1":"2"}},{"t":"case","label":"Woodford v. Garceau","cite":"538 U.S. 202","y":2003,"id":"2002/01-1862","sc":1,"op":1,"sum":"The Court held, for purposes of Lindh, that a case does not become \"pending\" until an actual application for habeas corpus relief is filed in federal court.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"usc","label":"42 U.S.C. § 12131","url":"https://www.law.cornell.edu/uscode/text/42/12131","by":{"1":"24"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"1":"9"}},{"t":"usc","label":"42 U.S.C. § 1997","url":"https://www.law.cornell.edu/uscode/text/42/1997","stext":{"head":"§1997. Definitions","paras":[[0,"As used in this subchapter—"],[0,"(1) The term \"institution\" means any facility or institution—"],[1,"(A) which is owned, operated, or managed by, or provides services on behalf of any State or political subdivision of a State; and"],[1,"(B) which is—"],[2,"(i) for persons who are mentally ill, disabled, or retarded, or chronically ill or handicapped;"],[2,"(ii) a jail, prison, or other correctional facility;"],[2,"(iii) a pretrial detention facility;"],[2,"(iv) for juveniles—"],[3,"(I) held awaiting trial;"],[3,"(II) residing in such facility or institution for purposes of receiving care or treatment; or"],[3,"(III) residing for any State purpose in such facility or institution (other than a residential facility providing only elementary or secondary education that is not an institution in which reside juveniles who are adjudicated delinquent, in need of supervision, neglected, placed in State custody, mentally ill or disabled, mentally retarded, or chronically ill or handicapped); or"],[2,"(v) providing skilled nursing, intermediate or long-term care, or custodial or residential care."],[0,"(2) Privately owned and operated facilities shall not be deemed \"institutions\" under this subchapter if—"],[1,"(A) the licensing of such facility by the State constitutes the sole nexus between such facility and such State;"],[1,"(B) the receipt by such facility, on behalf of persons residing in such facility, of payments under title XVI, XVIII [42 U.S.C. 1381 et seq., 1395 et seq.], or under a State plan approved under title XIX [42 U.S.C. 1396 et seq.], of the Social Security Act, constitutes the sole nexus between such facility and such State; or"],[1,"(C) the licensing of such facility by the State, and the receipt by such facility, on behalf of persons residing in such facility, of payments under title XVI, XVIII [42 U.S.C. 1381 et seq., 1395 et seq.], or under a State plan approved under title XIX [42 U.S.C. 1396 et seq.], of the Social Security Act, constitutes the sole nexus between such facility and such State;"],[0,"(3) The term \"person\" means an individual, a trust or estate, a partnership, an association, or a corporation;"],[0,"(4) The term \"State\" means any of the several States, the District of Columbia, the Commonwealth of Puerto Rico, or any of the territories and possessions of the United States;"],[0,"(5) The term \"legislative days\" means any calendar day on which either House of Congress is in session."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1997?type=usc&year=mostrecent&link-type=html"},"head":"§1997. Definitions","tname":"The Public Health and Welfare","by":{"1":"10","3":"20"}},{"t":"usc","label":"18 U.S.C. § 241","url":"https://www.law.cornell.edu/uscode/text/18/241","by":{"1":"1, 13"}},{"t":"usc","label":"18 U.S.C. § 3123","url":"https://www.law.cornell.edu/uscode/text/18/3123","subs":["(b)(2)"],"by":{"1":"12"}},{"t":"usc","label":"28 U.S.C. § 2243","url":"https://www.law.cornell.edu/uscode/text/28/2243","stext":{"head":"§2243. Issuance of writ; return; hearing; decision","paras":[[0,"A court, justice or judge entertaining an application for a writ of habeas corpus shall forthwith award the writ or issue an order directing the respondent to show cause why the writ should not be granted, unless it appears from the application that the applicant or person detained is not entitled thereto."],[0,"The writ, or order to show cause shall be directed to the person having custody of the person detained. It shall be returned within three days unless for good cause additional time, not exceeding twenty days, is allowed."],[0,"The person to whom the writ or order is directed shall make a return certifying the true cause of the detention."],[0,"When the writ or order is returned a day shall be set for hearing, not more than five days after the return unless for good cause additional time is allowed."],[0,"Unless the application for the writ and the return present only issues of law the person to whom the writ is directed shall be required to produce at the hearing the body of the person detained."],[0,"The applicant or the person detained may, under oath, deny any of the facts set forth in the return or allege any other material facts."],[0,"The return and all suggestions made against it may be amended, by leave of court, before or after being filed."],[0,"The court shall summarily hear and determine the facts, and dispose of the matter as law and justice require."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2243?type=usc&year=mostrecent&link-type=html"},"head":"§2243. Issuance of writ; return; hearing; decision","tname":"Judiciary and Judicial Procedure","by":{"1":"21","2":"31"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","by":{"1":"2, 21, 23, 27"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"1":"2, 7, 14, 22"}},{"t":"case","label":"Adams v. United States ex rel. McCann","cite":"317 U.S. 269","y":1942,"id":"scdb/1942-001","sc":1,"sum":"that for its aid in deciding this question the Circuit Court of Appeals had jurisdiction under Judicial Code § 262 to issue a writ of habeas corpus. P: 274.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"passim","3":"14"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"2":"20, 24","3":"2, 3"}},{"t":"case","label":"Ayestas v. Davis","cite":"138 S. Ct. 1080","y":2018,"id":"2017/16-6795","sc":1,"ar":3,"sum":"The Court decided that the district court's denial of petitioner's request for \"reasonably necessary\" investigative and related services under 18 U.S.C. § 3599(f) to prove that he was entitled to federal habeas relief was a judicial decision subject to appellate review under the standard jurisdictional provisions; and that the U.S. Court of Appeals for the 5th Circuit applied the wrong legal standard in affirming the district court's denial of petitioner's § 3599(f) request.","sumSrc":"Oyez","by":{"2":"42, 44, 49","3":"21"}},{"t":"case","label":"Catlin v. United States","cite":"324 U.S. 229","y":1945,"id":"scdb/1944-071","sc":1,"sum":"1. In a proceeding instituted by a petition in the District Court for the condemnation of land under the War Purposes Act of 1917, a \"judgment\" entered upon a declaration of taking filed pursuant to the Declaration of Taking Act of 1931, and a subsequent order denying the landowner's motion to vacate the judgment and to dismiss the petition, held not \"final decisions\" under § 128 of the Judicial Code and therefore …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"Cobbledick v. United States","cite":"309 U.S. 323","y":1940,"id":"scdb/1939-076","sc":1,"sum":"An order of the District Court denying a motion to quash a subpoena duces tecum requiring one to appear with papers and testify before a grand jury is not a \"final decision\" within the meaning of Jud. Code § 128 (a). Pp. 324, 330. 107 F. 2d 975, affirmed. CERTIORARI, 308 U. S. 547, to review judgments dismissing, for want of jurisdiction, appeals from orders denying motions to quash subpoenas duces tecum. Mr. Donald …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"Cohen v. Beneficial Indus. Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"op":6,"ar":6,"sum":"1. Under 28 U. S. C. § 1291, appeal may be. taken from an order of a Federal District Court denying a corporation's motion that the plaintiff in a stockholder's derivative action be required, pursuant to a state statute, to give security for reasonable expenses of the defendants, in connection with the action.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"passim"}},{"t":"case","label":"Coopers & Lybrand v. Livesay","cite":"437 U.S. 463","y":1978,"id":"1977/76-1836","sc":1,"sum":"Respondents, who had purchased securities in reliance on a prospectus, brought this action on behalf of themselves and a class of similarly situated purchasers, alleging that petitioner accounting firm had violated the federal securities laws. The District Court first certified the action as a class action under Fed. Rule Civ. Proc. 23, and then, after further proceedings, decertified the class. Respondents then …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"Dietz v. Bouldin","cite":"579 U.S. 40","y":2016,"id":"2015/15-458","sc":1,"sum":"The Court determined that a federal district court judge has some ability to recall jurors in a civil case after identifying an error in their verdict, subject to certain limitations to ensure the jurors were not prejudiced.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"Firestone Tire & Rubber Co. v. Risjord","cite":"449 U.S. 368","y":1981,"id":"1980/79-1420","sc":1,"sum":"Respondent is lead counsel for the plaintiffs in four consolidated productliability suits in Federal District Court against petitioner and other manufacturers. Petitioner moved to disqualify respondent from further representation of the plaintiffs because of an alleged conflict of interest arising from the fact that petitioner's liability insurer was also an occasional client of respondent's law firm. Petitioner …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19, 40, 43"}},{"t":"case","label":"Johnson v. Jones","cite":"515 U.S. 304","y":1995,"id":"1994/94-455","sc":1,"op":3,"sum":"The Court held that a defendant, who is entitled to invoke a qualified immunity defense, may not appeal a District Court's summary judgment order insofar as that order determines whether or not the pretrial record sets forth a genuine issue of fact for trial.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Link v. Wabash R. Co.","cite":"370 U.S 626","y":1962,"url":"https://www.courtlistener.com/c/U.S/370/626/","by":{"2":"41"}},{"t":"case","label":"McFarland v. Scott","cite":"512 U.S. 849","y":1994,"id":"1993/93-6497","sc":1,"sum":"Title 21 U. S. C. §848(q)(4)(B) entitles capital defendants to qualified legal representation in any \"post conviction proceeding\" under 28 U. S. C. §2254 or §2255, sections of the federal habeas corpus statute. Having failed to obtain a modification of his impending execution date in Texas state court, petitioner McFarland commenced this action in the Federal District Court by filing a pro se motion stating that he …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"10"}},{"t":"case","label":"Miller v. Hambrick","cite":"905 F.2d 259","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/905/259/","sum":"Finding that district court lacked jurisdiction to hear a habeas petition filed by a prisoner who was present pursuant to a Section 2241(c)(5) writ because “[t]he [habeas corpus ad testificandum] writ authorizes a trip not a change of custodians”.","sumSrc":"brief:2","by":{"2":"38"}},{"t":"case","label":"Mohawk Indus., Inc. v. Carpenter","cite":"558 U.S. 100","y":2009,"id":"2009/08-678","sc":1,"op":5,"ar":8,"sum":"The Court held that disclosure orders adverse to attorney-client privilege do not qualify for immediate appeal under the collateral order doctrine.","sumSrc":"Oyez","by":{"2":"passim","3":"1, 4, 7"}},{"t":"case","label":"Ortiz v. Jordan","cite":"562 U.S. 180","y":2011,"id":"2010/09-737","sc":1,"op":1,"sum":"The Court held that a party may not appeal a denial of summary judgement after a district court has conducted a full trial on the merits.","sumSrc":"Oyez","by":{"2":"24","3":"6"}},{"t":"case","label":"Sell v. United States","cite":"539 U.S. 166","y":2003,"id":"2002/02-5664","sc":1,"sum":"The Court held that the Constitution allows the Federal Government to administer antipsychotic drugs, even against the defendant's will, in limited circumstances.","sumSrc":"Oyez","by":{"2":"21","3":"3, 6"}},{"t":"case","label":"State v. Twyford","cite":"833 N.E.2d 289","y":2005,"court":"Ohio","url":"https://www.courtlistener.com/c/N.E.2d/833/289/","by":{"2":"8"}},{"t":"case","label":"Swint v. Chambers Cnty. Comm’n","cite":"514 U.S. 35","y":1995,"id":"1994/93-1636","sc":1,"sum":"The Eleventh Circuit lacked jurisdiction to rule on the county commission's liability at this interlocutory stage of the litigation and, accordingly, should have dismissed the commission's appeal.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19, 20, 21, 25"}},{"t":"case","label":"Will v. Hallock","cite":"546 U.S. 345","y":2006,"id":"2005/04-1332","sc":1,"op":1,"sum":"The Court ruled that the Circuit Court had no jurisdiction to hear an appeal under the collateral order doctrine. Writing for the Court, Justice David Souter stressed the narrow scope of the doctrine. The Court reiterated that only orders that cannot be \"effectively\" reviewed after a final judgment can be appealed before the close of the trial.","sumSrc":"Oyez","by":{"2":"1, 19, 21","3":"3"}},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"sum":"The Court held that \"the statute, read in light of the Constitution's demands, limits an alien's post-removal-period detention to a period reasonably necessary to bring about that alien's removal from the United States\" and \"does not permit indefinite detention.\" \"Based on our conclusion that indefinite detention of aliens in the former category would raise serious constitutional concerns, we construe the statute to contain an implicit 'reasonable time' limitation, the application of which is subject to federal court review,\" wrote Justice Breyer.","sumSrc":"Oyez","by":{"2":"37"}},{"t":"usc","label":"28 U.S.C. § 453","url":"https://www.law.cornell.edu/uscode/text/28/453","subs":["(1946)"],"stext":{"head":"§453. Oaths of justices and judges","paras":[[0,"Each justice or judge of the United States shall take the following oath or affirmation before performing the duties of his office: \"I, ______ XXX, do solemnly swear (or affirm) that I will administer justice without respect to persons, and do equal right to the poor and to the rich, and that I will faithfully and impartially discharge and perform all the duties incumbent upon me as ______ under the Constitution and laws of the United States. So help me God.\""]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/453?type=usc&year=mostrecent&link-type=html"},"head":"§453. Oaths of justices and judges","tname":"Judiciary and Judicial Procedure","by":{"2":"32","3":"13"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","subs":["(b)"],"by":{"2":"22"}},{"t":"usc","label":"28 U.S.C. § 2072","url":"https://www.law.cornell.edu/uscode/text/28/2072","subs":["(c)"],"stext":{"head":"§2072. Rules of procedure and evidence; power to prescribe","paras":[[0,"(a) The Supreme Court shall have the power to prescribe general rules of practice and procedure and rules of evidence for cases in the United States district courts (including proceedings before magistrate judges thereof) and courts of appeals."],[0,"(b) Such rules shall not abridge, enlarge or modify any substantive right. All laws in conflict with such rules shall be of no further force or effect after such rules have taken effect."],[0,"(c) Such rules may define when a ruling of a district court is final for the purposes of appeal under section 1291 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2072?type=usc&year=mostrecent&link-type=html"},"head":"§2072. Rules of procedure and evidence; power to prescribe","tname":"Judiciary and Judicial Procedure","by":{"2":"21","3":"6, 19"}},{"t":"case","label":"Armstrong v. Exceptional Child Center, Inc.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"sum":"A case that determines whether or not a private right of action exists under the Medicaid Act.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"Brecht v. Abrahamson","cite":"507 U.S. 619","y":1993,"id":"1992/91-7358","sc":1,"sum":"Chief Justice William H. Rehnquist wrote that the \"substantial and injurious effect\" test was preferable to the \"beyond a reasonable doubt\" test in requests for habeas corpus relief. Habeas proceedings are not to be the primary avenue for resolving disputes; Rehnquist called the writ \"an extraordinary remedy\", reserved for the victims of grave injustice.","sumSrc":"Oyez","by":{"3":"10"}},{"t":"case","label":"Calderon v. Thompson","cite":"521 U.S. 1136","y":1997,"url":"https://supreme.justia.com/cases/federal/us/521/1136/","sc":1,"op":2,"by":{"3":"8"}},{"t":"case","label":"Carlsbad Tech., Inc. v. HIF Bio, Inc.","cite":"556 U.S. 635","y":2009,"id":"2008/07-1437","sc":1,"sum":"The Court held that a district court's declination of supplemental jurisdiction is not a dismissal for which federal appellate review is barred.","sumSrc":"Oyez","by":{"3":"4"}},{"t":"case","label":"Eisen v. Carlisle & Jacquelin","cite":"417 U.S. 156","y":1974,"id":"1973/73-203","sc":1,"sum":"Petitioner brought a class action under Fed. Rule Civ. Proc. 23 on behalf of himself and all odd-lot traders on the New York Stock Exchange for a certain four-year period, charging respondent brokerage firms, which handled 99% of the Exchange's odd-lot business, and respondent Exchange with violating the antitrust and securities laws. There followed a series of decisions by the District Court and the Court of …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"3"}},{"t":"case","label":"Foy v. United States","cite":"285 F.R.D. 407","y":2012,"court":"N.D. Iowa","url":"https://www.courtlistener.com/c/F.R.D./285/407/","by":{"3":"17"}},{"t":"case","label":"Garland v. Sullivan","cite":"737 F.2d 1283","y":1984,"court":"3rd Cir.","url":"https://www.courtlistener.com/c/F.2d/737/1283/","by":{"3":"4"}},{"t":"case","label":"Harlow v. Fitzgerald","cite":"457 U.S. 800","y":1982,"id":"1981/80-945","sc":1,"sum":"The Court held that government officials are entitled to qualified immunity but not absolute immunity. Absolute immunity is only available for specific functions that require a total shield from liability.","sumSrc":"Oyez","by":{"3":"2"}},{"t":"case","label":"Henderson v. United States","cite":"517 U.S. 654","y":1996,"id":"1995/95-232","sc":1,"sum":"The Court held that \"[t]he federal rules thus convey a clear message: Complaints are not to be dismissed if served within 120 days, or within such additional time as the court may allow.\".","sumSrc":"Oyez","by":{"3":"19"}},{"t":"case","label":"Kimble v. Marvel Entm’t, LLC","cite":"576 U.S. 446","y":2015,"id":"2014/13-720","sc":1,"sum":"The Court determined that its earlier decision in Brulotte v. Thys Co. , which held that a patentee cannot continue to receive royalties after the expiration of the patent, should be upheld.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Lamar, Archer & Cofrin, LLP v. Appling","cite":"138 S. Ct. 1752","y":2018,"id":"2017/16-1215","sc":1,"sum":"The Court decided that a statement regarding a specific asset can be a “statement respecting the debtor’s . . . financial condition” under section 523(a)(2)(B) of the Bankruptcy Code.","sumSrc":"Oyez","by":{"3":"6"}},{"t":"case","label":"Mitchell v. Forsyth","cite":"472 U.S. 511","y":1985,"id":"1984/84-335","sc":1,"sum":"In 1970, petitioner, who was then the Attorney General, authorized a warrantless wiretap for the purpose of gathering intelligence regarding the activities of a radical group that had made tentative plans to take actions threatening the Nation's security. During the time the wiretap was installed, the Government intercepted three conversations between a member of the group and respondent. Thereafter, this Court in …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"2, 3"}},{"t":"case","label":"Moore v. Texas","cite":"139 S. Ct. 666","y":2019,"id":"2018/18-443","sc":1,"op":2,"ar":1,"sum":"The Texas Court of Criminal Appeals’ redetermination that Moore does not have an intellectual disability and is thus eligible for the death penalty is inconsistent with Moore v. Texas, 581 U. S. ___.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"22"}},{"t":"case","label":"Moses H. Cone Mem’l Hosp. v. Mercury Constr. Corp.","cite":"460 U.S. 1","y":1983,"id":"1982/81-1203","sc":1,"sum":"Petitioner, a hospital located in North Carolina, entered into a contract with respondent contractor, an Alabama corporation, for construction of additions to the hospital building. Contract disputes were to be initially referred to the architect who was hired to design and oversee the construction project. Disputes decided by the architect or not decided within a specified time could be submitted to binding …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"3"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"141 S. Ct. 1474","y":2021,"id":"2020/19-863","sc":1,"sum":"A notice to appear sufficient to trigger the Illegal Immigration Reform and Immigrant Responsibility Act of 1996’s stop-time rule is a single document containing all the information about an individual’s removal hearing specified in 8 U. S. C. §1229(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"3":"18"}},{"t":"case","label":"Osborn v. Haley","cite":"549 U.S. 225","y":2007,"id":"2006/05-593","sc":1,"ar":1,"sum":"The Court upheld the Sixth Circuit and ruled that \"Westfall Act certification is proper when a federal officer charged with misconduct asserts, and the Attorney General concludes, that the incident or episode in suit never occurred.\" The opinion by Justice Ruth Bader Ginsburg held that the Act would be ineffective at shielding federal employees from suit if the government were required to accept for immunity purposes the plaintiff's allegation that the event in question occurred.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Puerto Rico Aqueduct & Sewer Auth. v. Metcalf & Eddy, Inc.","cite":"506 U.S. 139","y":1993,"id":"1992/91-1010","sc":1,"op":1,"sum":"States and state entities that claim to be \"arms of the State\" may take advantage of the collateral order doctrine of Cohen v. Beneficial Industrial Loan Corp., 337 U. S. 541, to appeal a district court order denying a claim of Eleventh Amendment immunity from suit in federal court. Although 28 U. S. C. § 1291 requires that appeals be taken from \"final decisions of the district courts,\" Cohen, supra, at 546, …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"2, 3, 6"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"3":"19"}},{"t":"case","label":"Roberts v. United States Dist. Ct.","cite":"339 U.S. 844","y":1950,"id":"scdb/1949-096","sc":1,"by":{"3":"3"}},{"t":"case","label":"Schlagenhauf v. Holder","cite":"379 U.S. 104","y":1964,"id":"1964/8","sc":1,"sum":"A bus collided with the rear of a tractor-trailer and a diversity action for damages was brought by certain bus passengers in the District Court. The defendants-the bus company, petitioner its driver, the owners of the tractor and the trailer (hereinafter codefendants), and the tractor driver-filed answers denying negligence. The bus company cross-claimed against codefendants for damage to its bus, claiming that the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"8"}},{"t":"case","label":"Stack v. Boyle","cite":"342 U.S. 1","y":1951,"id":"scdb/1951-001","sc":1,"sum":"Bail has not been fixed by proper methods in this case.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"5"}},{"t":"case","label":"Stolt-Nielsen S.A. v. AnimalFeeds Int’l Corp.","cite":"559 U.S. 662","y":2010,"id":"2009/08-1198","sc":1,"sum":"The Court held that imposing class arbitration on parties who have not agreed to authorize class arbitration is inconsistent with the Federal Arbitration Act.","sumSrc":"Oyez","by":{"3":"1"}},{"t":"case","label":"Trevino v. Thaler","cite":"569 U.S. 413","y":2013,"id":"2012/11-10189","sc":1,"sum":"The Court found that procedural default will not bar a federal court from hearing a claim of ineffective assistance of trial counsel.","sumSrc":"Oyez","by":{"3":"10"}},{"t":"case","label":"Union Pac. Ry. Co. v. Botsford","cite":"141 U.S. 250","y":1891,"id":"scdb/1890-309","sc":1,"sum":"A court of the United States cannot order a plaintiff, in an action for an injury to the person, to submit to a surgical examination in advance of the trial.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"15"}},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"ar":5,"sum":"The Court held that the President does not have executive privilege in immunity from subpoenas or other civil court actions.","sumSrc":"Oyez","by":{"3":"7"}},{"t":"case","label":"Williams v. Homeland Ins. Co.","cite":"18 F.4th 806","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/18/806/","op":4,"by":{"3":"5"}},{"t":"usc","label":"18 U.S.C. § 4244","url":"https://www.law.cornell.edu/uscode/text/18/4244","by":{"3":"10, 11"}},{"t":"usc","label":"18 U.S.C. § 4245","url":"https://www.law.cornell.edu/uscode/text/18/4245","by":{"3":"10, 11"}},{"t":"usc","label":"42 U.S.C. § 12133","url":"https://www.law.cornell.edu/uscode/text/42/12133","by":{"3":"20"}},{"t":"rule","label":"Fed. R. App. P. 3","url":"https://www.law.cornell.edu/rules/frap/rule_3","by":{"3":"6"}},{"t":"rule","label":"Fed. R. Civ. P. 34","url":"https://www.law.cornell.edu/rules/frcp/rule_34","by":{"3":"16"}},{"t":"rule","label":"Fed. R. Civ. P. 45","url":"https://www.law.cornell.edu/rules/frcp/rule_45","by":{"3":"16"}},{"t":"rule","label":"Fed. R. Civ. P. 65","url":"https://www.law.cornell.edu/rules/frcp/rule_65","by":{"3":"20"}},{"t":"rule","label":"Fed. R. Crim. P. 16","url":"https://www.law.cornell.edu/rules/frcrmp/rule_16","by":{"3":"16"}},{"t":"rule","label":"Fed. R. Crim. P. 17","url":"https://www.law.cornell.edu/rules/frcrmp/rule_17","by":{"3":"16"}}]};